366:  * g_variant_ensure_size:
367:  * @value: a #GVariant
368:  *
369:  * Ensures that the ->size field of @value is filled in properly.  This
370:  * must be done as a precursor to any serialization of the value in
371:  * order to know how large of a buffer is needed to store the data.
372:  *
373:  * The current thread must hold the lock on @value.
374:  */
375: static void
376: g_variant_ensure_size (GVariant *value)
377: {
378:   g_assert (value->state & STATE_LOCKED);
379: 
380:   if (value->size == (gsize) -1)
381:     {
382:       gpointer *children;
383:       gsize n_children;
