518:  *
519:  * The current thread must hold the lock on @value.
520:  */
521: static void
522: g_variant_ensure_serialised (GVariant *value)
523: {
524:   g_assert (value->state & STATE_LOCKED);
525: 
526:   if (~value->state & STATE_SERIALISED)
