629:       gsize aligned_size = g_bytes_get_size (bytes);
630: 
631:       /* posix_memalign() requires the alignment to be a multiple of
632:        * sizeof(void*), and a power of 2. See g_variant_type_info_query() for
633:        * details on the alignment format. */
634:       if (posix_memalign (&aligned_data, MAX (sizeof (void *), alignment + 1),
635:                           aligned_size) != 0)
636:         g_error ("posix_memalign failed");
637: 
638:       if (aligned_size != 0)
639:         memcpy (aligned_data, g_bytes_get_data (bytes, NULL), aligned_size);
640: 
641:       bytes = owned_bytes = g_bytes_new_with_free_func (aligned_data,
642:                                                         aligned_size,
643:                                                         free, aligned_data);
644:       aligned_data = NULL;
645: #else
